#include "test_common.h"
#include "report_management.h"
static void test_empty_summary(void){BmsDonorContext_t d;BmsHospitalContext_t h;BmsInventoryContext_t i;BmsBloodRequestContext_t r;BmsDonationContext_t dn;BmsEmergencyAlertContext_t a;BmsSummaryReport_t s;ASSERT_OK(DonorManagementInitialize(&d));ASSERT_OK(HospitalManagementInitialize(&h));ASSERT_OK(BloodInventoryInitialize(&i));ASSERT_OK(BloodRequestManagementInitialize(&r));ASSERT_OK(DonationManagementInitialize(&dn));ASSERT_OK(EmergencyAlertManagementInitialize(&a));ASSERT_OK(ReportManagementBuildSummary(&d,&h,&i,&r,&dn,&a,&s));CU_ASSERT_EQUAL(s.totalDonors,0U);CU_ASSERT_EQUAL(s.totalHospitals,0U);CU_ASSERT_EQUAL(s.totalInventoryUnits,0U);CU_ASSERT_EQUAL(s.pendingRequests,0U);CU_ASSERT_EQUAL(s.totalDonations,0U);ASSERT_OK(ReportManagementPrintSummary(&s));EmergencyAlertManagementDeinitialize(&a);DonationManagementDeinitialize(&dn);BloodRequestManagementDeinitialize(&r);BloodInventoryDeinitialize(&i);HospitalManagementDeinitialize(&h);DonorManagementDeinitialize(&d);}
void RegisterReportTests(void){CU_pSuite s=CU_add_suite("Reports",NULL,NULL);CU_add_test(s,"empty operational summary",test_empty_summary);}
